import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Library crates are exposed as Platform plugins","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0001-library-crates-are-platform-plugins.md","filePath":"vendored/handl/project/adrs/0001-library-crates-are-platform-plugins.md"}`),a={name:`handl/project/adrs/0001-library-crates-are-platform-plugins.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="library-crates-are-exposed-as-platform-plugins" tabindex="-1">Library crates are exposed as Platform plugins <a class="header-anchor" href="#library-crates-are-exposed-as-platform-plugins" aria-label="Permalink to “Library crates are exposed as Platform plugins”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The <code>crates/</code> directory contains two overlapping categories:</p><ul><li><code>lib-*</code> crates: standard library implementations (e.g. <code>lib-json</code>, <code>lib-crypto</code>, <code>lib-hello</code>).</li><li><code>plugin-*</code> crates: plugins that contribute rules to the host (e.g. <code>plugin-eval-hello</code>, <code>plugin-runtime-arithmetic</code>, <code>plugin-grammar-array</code>).</li></ul><p>Currently only <code>lib-hello</code> follows a registration pattern where the crate itself implements the <code>Plugin</code> trait. Its <code>HelloLibraryPlugin</code> contributes a concrete <code>HelloPlugin</code> to the host so that <code>hello.greet</code> is available at runtime. The majority of <code>lib-*</code> crates are plain libraries and are not directly loadable by the host, which makes the boundary between &quot;library&quot; and &quot;plugin&quot; ambiguous.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Every standard-library crate is a Platform plugin:</p><ol><li>The crate name is prefixed with <code>plugin-lib-</code> (e.g. <code>plugin-lib-json</code>, <code>plugin-lib-crypto</code>) to make the plugin role explicit and consistent with the <code>plugin-*</code> family.</li><li>Each crate contains a <code>plugin</code> module that exposes a minimal <code>Plugin</code> implementation.</li><li>The plugin&#39;s <code>id</code> is <code>lib.&lt;name&gt;</code> (e.g. <code>lib.json</code>), and its <code>contribute</code> method registers the concrete library implementation(s) with the host.</li><li>The plugin does not declare capabilities of its own unless the library is directly invokable; its purpose is to add the library&#39;s rules/modules to the host.</li><li><code>plugin-lib-type</code> keeps its <code>Plugin</code> module behind a <code>plugin</code> feature so that consumers that only need the type definitions (such as <code>handl-platform</code>) can depend on it with the feature disabled, while the host can enable the <code>plugin</code> feature to load it.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>plugin-*</code> crates that consume a library (e.g. <code>plugin-eval-hello</code>) will depend on <code>plugin-lib-*</code> crates instead of <code>lib-*</code> crates.</li><li>All library crates gain a runtime identity, which simplifies host loading, kit manifests, and dependency resolution.</li><li>The refactor touches the workspace <code>Cargo.toml</code>, all <code>lib-*</code> crate directories, and every crate that depends on them.</li><li>The <code>lib-</code> prefix is removed from crate names, so references in docs and kits must be updated.</li><li><code>plugin-lib-type</code> remains a regular library crate because the circular dependency with <code>handl-platform</code> cannot be broken without splitting out the core type definitions.</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>accepted</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};